// PLANTILLA de aventura: sustituye este marcador por tu escena 3D.
// Gestos: turnRight, lookUp. Sonido: window.folio.sfx.play("aventura")
var k = 0;
function init() { this.scale.setScalar(1); }
function turnRight() { k = 1; window.folio?.sfx.play("aventura"); }
function lookUp() { k = 1; window.folio?.sfx.play("pop"); }
function update(event) { k = Math.max(0, k - event.delta / 700); this.scale.setScalar(1 + k * 1.5); this.rotation.y += event.delta / 800; }
